'use strict';

define('forum/header/notifications', function () {
	const notifications = {};

	notifications.prepareDOM = function () {
		const notifTrigger = $('[component="notifications"] [data-bs-toggle="dropdown"]');

		notifTrigger.on('show.bs.dropdown', (ev) => {
			requireAndCall('loadNotifications', $(ev.target).parent().find('[component="notifications/list"]'));
		});

		notifTrigger.each((index, el) => {
			const dropdownEl = $(el).parent().find('.dropdown-menu');
			if (dropdownEl.hasClass('show')) {
				requireAndCall('loadNotifications', dropdownEl.find('[component="notifications/list"]'));
			}
		});

		socket.removeListener('event:new_notification', onNewNotification);
		socket.on('event:new_notification', onNewNotification);

		socket.removeListener('event:notifications.updateCount', onUpdateCount);
		socket.on('event:notifications.updateCount', onUpdateCount);
	};

	function onNewNotification(data) {
		requireAndCall('onNewNotification', data);
	}

	function onUpdateCount(data) {
		requireAndCall('updateNotifCount', data);
	}

	function requireAndCall(method, param) {
		require(['notifications'], function (notifications) {
			notifications[method](param);
		});
	}

	return notifications;
});

	selector.getSelectedCid = function () {
		return selector.selectedCategory ? selector.selectedCategory.cid : 0;
	};

	if (options.hasOwnProperty('selectedCategory')) {
		app.parseAndTranslate(options.template, { selectedCategory: options.selectedCategory }, function (html) {
			selector.el.find('[component="category-selector-selected"]').html(
				html.find('[component="category-selector-selected"]').html()
			);
		});
	}
	return selector;
};

categorySelector.modal = function (options) {
	options = options || {};
	options.onSelect = options.onSelect || function () {};
	options.onSubmit = options.onSubmit || function () {};
	app.parseAndTranslate('admin/partials/categories/select-category', { message: options.message }, function (html) {
		const modal = bootbox.dialog({
			title: options.title || '[[modules:composer.select-category]]',
			message: html,
			buttons: {
				save: {
					label: '[[global:select]]',
					className: 'btn-primary',
					callback: submit,
				},
			},
		});

		const selector = categorySelector.init(modal.find('[component="category-selector"]'), options);
		function submit(ev) {
			ev.preventDefault();
			if (selector.selectedCategory) {
				options.onSubmit(selector.selectedCategory);
				modal.modal('hide');
			}
			return false;
		}
		if (options.openOnLoad) {
			modal.on('shown.bs.modal', function () {
				modal.find('.dropdown-toggle').dropdown('toggle');
			});
		}
		modal.find('form').on('submit', submit);
	});
};

return categorySelector;

